function identity_switch_init(){rcmail.addEventListener("plugin.identity_switch_newmail",identity_switch_newmail);rcmail.addEventListener("plugin.identity_switch_notify",identity_switch_notify);rcmail.addEventListener("init",function(){if(rcmail.message_list){rcmail.message_list.addEventListener("select",identity_switch_stop_notify)}})}function identity_switch_newmail(a){for(var b=0;b<a.length;b++){if(!a[0].init){setTimeout(identity_switch_check_newmail,20,a[b].iid)}if(a[0].logging=="2"){var c=new Date();console.log(c.toLocaleString("de-DE")+" "+a[b].iid+": Start ckecking in "+a[b].wait+" seconds")}setInterval(identity_switch_check_newmail,a[b].wait*1000,a[b].iid)}}function identity_switch_check_newmail(a){rcmail.http_post("plugin.identity_switch_newmail",{identity_switch_iid:a})}function identity_switch_run(a){rcmail.env.unread_counts={};rcmail.http_post("plugin.identity_switch_run",{identity_switch_iid:a})}function identity_switch_notify(a){var c=decodeURI(a[0].autoplay);var g=decodeURI(a[0].notification);var j=decodeURI(a[0].title);for(var b=1;b<a.length;b++){var f=$("#identity_switch_unseen_"+a[b].iid);if(a[b].unseen=="0"){f.text("")}else{f.text(a[b].unseen)}if(a[0].logging=="2"){var h=new Date();console.log(h.toLocaleString("de-DE")+" "+a[b].iid+": Changing unseen from "+a[b].old+" to "+a[b].unseen)}if(a[b].basic!==undefined){identity_switch_notify_basic()}if(a[b].desktop!==undefined){identity_switch_notify_desktop(j,a[b].desktop.text,a[b].desktop.timeout,g)}if(a[b].sound!==undefined){identity_switch_notify_sound(c)}}}function identity_switch_stop_notify(a){if(rcmail.env.favicon_href&&rcmail.env.favicon_changed&&(!a||a.action!="check-recent")){$('<link rel="shortcut icon" href="'+rcmail.env.favicon_href+'"/>').replaceAll('link[rel="shortcut icon"]');rcmail.env.favicon_changed=0}}function identity_switch_notify_basic(){var b=rcmail.is_framed()?window.parent:window;b.focus();var d=rcmail.assets_path("plugins/identity_switch/assets");var c=$('<link rel="shortcut icon">').attr("href",d+"/alert.ico");var a=$('link[rel="shortcut icon"]',b.document);if(!rcmail.env.favicon_href){rcmail.env.favicon_href=a.attr("href")}rcmail.env.favicon_changed=1;c.replaceAll(a)}function identity_switch_notify_desktop(d,c,b,e){if(!("Notification" in window)||window.Notification.permission!=="granted"){alert(decodeURIComponent(e));window.Notification.requestPermission();return}var a=new window.Notification(decodeURIComponent(d),{dir:"auto",lang:"",body:decodeURIComponent(c),icon:rcmail.assets_path("plugins/identity_switch/assets/alert.gif")});a.onclick=function(){this.close()};setTimeout(function(){a.close()},b*1000)}function identity_switch_notify_sound(b){var a=rcmail.assets_path("plugins/identity_switch/assets/alert");if(!("Notification" in window)||window.Notification.silent){alert(decodeURIComponent(b));return}if(!("Navigator" in window)&&window.Navigator.getAutoplayPolicy&&window.Navigator.getAutoplayPolicy("mediaelement")!="allowed"){alert(decodeURIComponent(b));window.Notification.requestPermission();return}new Audio(a+".mp3").play()}function identity_switch_toggle_menu(b){var a=$("#identity_switch_dropdown");if(a.is(":hidden")){a.show();$("#messagelist-fixedcopy").css("z-index","auto");a.scrollTop(b)}else{a.hide()}}$(document).click(function(a){if(a.button==0){var c=a.target.id;var b=$("#identity_switch_dropdown");if(c!="identity_switch_menu"&&!b.is(":hidden")){b.hide()}}});function identity_switch_stop_notify(a){if(rcmail.env.favicon_href&&rcmail.env.favicon_changed&&(!a||a.action!="check-recent")){$('<link rel="shortcut icon" href="'+rcmail.env.favicon_href+'"/>').replaceAll('link[rel="shortcut icon"]');rcmail.env.favicon_changed=0}}$(function(){var b=$("#identity_switch_menu");var a=false;if(b.length==0){return}switch(rcmail.env.skin){case"larry":a=identity_switch_skinLarry(b);break;case"classic":a=identity_switch_skinClassic(b);break;case"elastic":case"hivemail":a=identity_switch_skinElastic(b);break;default:alert('identity_switch plugin: Your skin "'+rcmail.env.skin+'" is not supported!');return}if(a){b.show()}else{alert("identity_switch plugin: Cannot show drop down menu!")}});function identity_switch_skinLarry(b){var a=$(".topright .username");if(a.length>0&&b.length>0){b.prependTo("#taskbar");a.hide();$("#identity_switch_menu").css("padding-top","4px").css("padding-bottom","4px");$("#identity_switch_dropdown").css("margin-left","-92px");return true}return false}function identity_switch_skinClassic(b){var a=$("#taskbar");if(a.length>0){a.prepend(b);$("#identity_switch_menu").css("left","-10px").css("top","-5px");$("#identity_switch_dropdown").css("left","190px").css("top","-40px");return true}return false}function identity_switch_skinElastic(d){var c=$(".header-title.username");d.css("background-color","transparent").css("padding","4px 0 0 2rem");if(c.length>0){c.prepend(d);c.css("margin-left","20px");var a=$(".header-title.username");var b=$("<"+a[0].nodeName+"/>");$.each(a[0].attributes,function(e,f){b.attr(f.name,f.value)});a.children().each(function(){b.append(this)});a.replaceWith(b);$("#identity_switch_menu").css("height","30px").css("width","180px");$("#identity_switch_dropdown").css("left","9px").css("margin-top","0");return true}return false}function identity_switch_fixIdent(a){if(parseInt(a)>0){$("#_from").val(a)}};